#!/usr/bin/env python3
# =====================================================================
#  apply_machine_id_hw.py  —  fence MACHINE_ID_HW_20261119   (on MACHINE_ID_STABLE_20261119, 12.0.7)
#
#  The licence id was sha256(system|machine|MAC). On every Intel Mac with a
#  T2 chip the T2 bridge en5 has the SAME MAC (ac:de:48:00:11:22), so a key +
#  token.jwt copied to another T2 Mac validated there. The id is now made from
#  the hardware UUID (macOS IOPlatformUUID, Windows MachineGuid), unique per
#  machine and independent of network interfaces.
#
#  No one is locked out: the client sends {machine_id: hardware id,
#  legacy_machine_id: MAC id}; the server moves a licence still bound to the
#  MAC id onto the hardware id at its next /heartbeat or /activate (compare-
#  and-set, Telegram ping "Machine id upgraded"). Old clients keep working.
#  If the client reaches a server from before this change it repeats the
#  request in the old shape (on a 422 or machine_mismatch), so deploy order
#  cannot lock anyone out, though the server should still go first.
#
#   backend/app/license/machine_id.py         hardware_id(), legacy_machine_id(), device_ids()
#   backend/app/license/license_client.py     post_device() (old-server fallback); heartbeat/activate
#   backend/app/jobs/liveness_ping.py         sends both ids via post_device
#   backend/app/license/test_machine_id_hw.py NEW  TC-LICHW-0001…0008
#   license_server/server.py                  legacy_machine_id field, _bound_here() move
#   license_server/db.py                      migrate_machine() CAS, 2 audit columns
#   license_server/notify.py                  notify_machine_migrated
#   license_server/admin_ui.html              HW / MAC badge on the binding
#   license_server/test_machine_id_hw_server.py NEW  TC-LICHW-0101…0108
#
#  Run ONLY this script:
#     cd ~/dev/scalp-app && python3 apply_machine_id_hw.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Rollout: 1) license_server/deploy-license-server.command (server first)
#           2) ./desktop/build-scalp.sh both, release 12.0.8
#  Rollback: free until a licence has moved; after that, an admin rebind for
#  each moved licence (its binding is the hardware id, which old code never sends).
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "MACHINE_ID_HW_20261119"
ITEMS = json.loads(r'''[{"path": "backend/app/license/machine_id.py", "orig": "b13a96e0a113d41ecfdad4cae6a9d86ec32f0eb0a425c8ad865756bfe5468a56", "new": "48a5b6478233c75f79b0a2c02346c88566a651efe171b05294584afbf84fde5c", "blob": ""}, {"path": "backend/app/license/license_client.py", "orig": "f3ac30cc9fb2802f768b6b034d581367d9475a57805a4b5a95172bcbdf1a80ad", "new": "0021242e1d20b9e0f1480e9c60e26b4e6f7151c235b4b81588b25f54ce7b1d30", "blob": ""}, {"path": "backend/app/jobs/liveness_ping.py", "orig": "b9d8ae268cac1f64ee84e9cc3a1677d23e33894f79ddb14c980f03b218b4d8e9", "new": "fdce642b6281aa78f0a9ccf2003ced444e53003dafe0bb6f29aea8c180e6a973", "blob": ""}, {"path": "backend/app/license/test_machine_id_hw.py", "orig": null, "new": "83587189063090e6ff3432843b7c03351953d107e2f2d255457138a4c0becafe", "blob": ""}, {"path": "license_server/server.py", "orig": "4e20f3cabc64b98054cc635250c284f9bb72d0931ab32596c154fb7933d829a5", "new": "3227039525de9d23c89b68ce7aacc77b67f32587981fc26e985a49d6cb6d10a4", "blob": ""}, {"path": "license_server/db.py", "orig": "df244739d7ae2455b12738fe54e1a9712752e9500706b5b918bc279024c8f1a3", "new": "8d6e82e45feb783ac6774d36b7a87b10ae1698d2005772c18a4c23e52c37942b", "blob": ""}, {"path": "license_server/notify.py", "orig": "a10a1616877bfe2ed8748a2a414a9ba799200e9abbc59767c43a7d827968646c", "new": "c9ab106a9d627a5d636e33c91293f460c393f96c8f2b54b56f1e13181b38d00f", "blob": ""}, {"path": "license_server/admin_ui.html", "orig": "241e1012b382fe3775ea8a117f701191aaa6cbf1e0a55f562fb96bb9339592a3", "new": "58e15e7d73137d97ae5d4a892ab94f2880dab67823e56199becf4e10c7643ff4", "blob": ""}, {"path": "license_server/test_machine_id_hw_server.py", "orig": null, "new": "56f0330d0f62a3dcf6f276af74c663ffe42c8ccee2e714b5e852425d5897bd7d", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/license/test_machine_id_hw.py", "app/license/test_machine_id_stable.py"]
SERVER_TESTS = ["test_machine_id_hw_server.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: MACHINE_ID_STABLE_20261119 (apply_machine_id_stable.py, 12.0.7)
if "--rollback" not in args:
    _pf = os.path.join(repo, "backend", "app", "license", "machine_id.py")
    if not os.path.exists(_pf) or "MACHINE_ID_STABLE_20261119" not in open(_pf, encoding="utf-8").read():
        die("backend/app/license/machine_id.py lacks MACHINE_ID_STABLE_20261119 — run apply_machine_id_stable.py (12.0.7) first")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    later = []
    for it, p, build in targets():
        if build or not os.path.exists(p) or not os.path.exists(p + ".bak-" + FENCE):
            continue
        with open(p, "rb") as f:
            if sha(f.read()) != it["new"]:
                later.append(os.path.relpath(p, repo))
    if later:
        die("cannot roll back — changed again after this script (by a later fix or a local edit): "
            + ", ".join(later) + ". Roll the later fixes back first, newest first. Nothing was changed.")
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped, later = [], 0, [], []
_applied = False                         # this script's marker is in the tree → it was applied
for it, p, build in targets():
    if not build and os.path.exists(p):
        with open(p, "rb") as f:
            if FENCE.encode() in f.read():
                _applied = True
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    if _applied:
        later.append(rel)                # applied, then changed by a later fix
        continue
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}"
        + (f"; {len(later)} changed again by later fixes" if later else "") + ") — nothing to do")
    sys.exit(0)
if later:
    die("partly applied: " + ", ".join(later) + " changed after this script while other files are "
        "not patched — check the tree (git status) before going on. Nothing was changed.")

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        # a planned file was just proven byte-identical to its expected base (sha == orig): only other drift stops us.
        _ok = {os.path.relpath(p, repo) for it, p, _c, b in plan if not b and it["orig"] is not None}
        dirty = [l for l in dirty if l[3:].strip() not in _ok]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="machine_id_hw_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, it["path"].replace("/", "_"))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        os.makedirs(os.path.dirname(p), exist_ok=True)   # a new file may need a new folder
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        # the project venv can lag requirements.txt (PyJWT): retry such a suite with this Python
        if (r is not None and r.returncode != 0 and "ModuleNotFoundError" in outp
                and "No module named 'app" not in outp and os.path.realpath(sys.executable) != os.path.realpath(py)):
            try:
                r = subprocess.run([sys.executable, t], cwd=backend, env=env, capture_output=True, text=True, timeout=900)
                outp = (r.stdout or "") + (r.stderr or "")
            except subprocess.TimeoutExpired:
                r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    # licence server suite: runs from license_server/ with this Python (fastapi, pydantic, PyJWT, cryptography)
    srv = os.path.join(repo, "license_server")
    for t in SERVER_TESTS:
        if not os.path.exists(os.path.join(srv, t)):
            continue
        try:
            r = subprocess.run([sys.executable, t], cwd=srv, capture_output=True, text=True, timeout=300)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ license_server/{t}  {last}")
        elif "ModuleNotFoundError" in outp:
            envmiss.append(t)
            say(f"  ? license_server/{t}  could not run here: {last}")
        else:
            failed.append("license_server/" + t)
            say(f"  ✗ license_server/{t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

# ── 5b. JSX parse gate (esbuild from frontend/node_modules, if installed) ──
_esb = os.path.join(repo, "frontend", "node_modules", ".bin", "esbuild")
if os.path.exists(_esb) and "--skip-tests" not in args:
    bad = []
    for it in ITEMS:
        if it["path"].startswith("frontend/src/") and it["path"].endswith((".jsx", ".js")):
            r = subprocess.run([_esb, os.path.join(repo, it["path"]), "--loader:.js=jsx", "--loader:.jsx=jsx",
                                "--log-level=error"], capture_output=True, text=True)
            if r.returncode != 0:
                bad.append(it["path"] + ": " + (r.stderr or "").strip()[:300])
    if bad:
        restore()
        die("JSX does not parse — every file restored:\n  " + "\n  ".join(bad))
    say("  ✓ esbuild parsed the changed frontend files")
else:
    say("  (esbuild not installed — the build will compile the frontend)")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)).")
say("  Next, in this order:")
say("    1. license_server/deploy-license-server.command   (server first; old clients keep working)")
say("    2. ./desktop/build-scalp.sh both, release 12.0.8   (each licence moves at its first heartbeat)")
say("  Undo: python3 apply_machine_id_hw.py --rollback  (after a licence has moved, it needs an admin rebind)")
